def queue_verified_users(apps, schema_editor):
    """이미 본인인증을 마친 계정마다 알릴 줄을 만든다. 워커가 결제 서버에 한 번씩 알린다."""
    IdentityVerification = apps.get_model('accounts', 'IdentityVerification')
    PaymentEligibility = apps.get_model('accounts', 'PaymentEligibility')
    now = django.utils.timezone.now()
    PaymentEligibility.objects.bulk_create(
        [
            PaymentEligibility(user_id=user_id, version=1, next_attempt_at=now)
            for user_id in IdentityVerification.objects.values_list('user_id', flat=True)
        ],
        ignore_conflicts=True,
    )


